my @f; find(sub { push @f, $File::Find::name if /\.go$/ && $File::Find::name !~ m{/(?:proto/gen|vendor)/} }, ".");
my (%d,%n);
for my $f (@f) { open my $h,"<",$f or next; local $/; my $s=<$h>; next if $s =~ /^\/\/ Code generated/m; while($s =~ /^func\s+(?:\([^)]*\)\s+)?([A-Za-z_]\w*)\s*\(/mg) { $d{$f.":".((substr($s,0,pos($s)) =~ tr/\n/\n)+1).":".$1}=1; $n{$1}++ if $f =~ m{^\./internal/}; }}
my @x; for my $k (keys %d) { my($f,$l,$name)=split /:/,$k,3; next unless $f =~ m{^\./internal/}; next if $n{$name} != 1; my $c=0; for my $g (@f) { open my $h,"<",$g; local $/; my $s=<$h>; next if $s =~ /^\/\/ Code generated/m; $c += ()=$s =~ /\b\Q$name\E\s*\(/g; } push @x, [$c-1,$k]; }
for (sort {$b->[0]<=>$a->[0]} @x[0..49]) { print "$_->[0]\t$_->[1]\n"; }
'

